ROWS = [
dict(id="T001", x="SOLVED (claimed, unrefereed), 14 Nov 2026: Kozma and Nitzan (arXiv:2401.12397) reduced theta(p_c) = 0 on Z^d, every d >= 2, to a correlation inequality for percolation on finite graphs; a proof of that inequality found by an AI system was released by OpenAI on 24 Sep 2026 (preprint 'Critical bond and site percolation on the cubic lattice', github.com/openai/math). Expositions: Blanc-Renaudie (arXiv:2610.10502) and Gouere (arXiv:2610.30063); Pei (arXiv:2611.01490) extends the result to long-range kernels with fast-decaying tails and cites a Lean 4/Mathlib formalisation of the all-dimensions statement. The quasi-transitive question of Benjamini and Schramm is the subject of a second OpenAI preprint of the same date ('No percolation at criticality on quasi-transitive graphs'), known here only from Pei's references and not read. Replacement row to be screened.", d="PERC", t="Continuity of the percolation phase transition on Z^d for 3 ≤ d ≤ 10",
 s="For Bernoulli bond (or site) percolation on Z^d at the critical point p_c there is almost surely no infinite open cluster: θ(p_c) = 0. Open for 3 ≤ d ≤ 10. Benjamini and Schramm ask the same for every quasi-transitive graph with p_c < 1.",
 c="The Benjamini–Schramm locator was confirmed on 14 Oct through Häggström, Percolation beyond Z^d: the contributions of Oded Schramm (Ann. Probab. 39, 2011, arXiv:1111.6763), Conjecture 2.5; the DOI matches Electron. Comm. Probab. 1 (1996), paper 8.",
 src="G. Grimmett, Percolation, 2nd ed. (Springer, 1999); I. Benjamini and O. Schramm, Percolation beyond Z^d, many questions and a few answers, Electron. Comm. Probab. 1 (1996)",
 loc="Benjamini–Schramm 1996, Conjecture 4 (confirmed: Häggström 2011, Conjecture 2.5); Grimmett 1999, Chapter 10 (to verify)",
 url="https://doi.org/10.1214/ECP.v1-978",
 why="The best-known open problem in percolation. A proof in d = 3 needs a method that works below the upper critical dimension, and none exists.",
 st="Proved for d = 2 (Harris 1960, Kesten 1980) and d ≥ 11 (Hara–Slade 1990 for d ≥ 19; Fitzner–van der Hofstad 2017 for d ≥ 11), in half-spaces (Barsky–Grimmett–Newman 1991), on slabs Z^2 × {0,…,k} (Duminil-Copin–Sidoravicius–Tassion 2016), on nonamenable unimodular graphs (Benjamini–Lyons–Peres–Schramm 1999), on graphs of exponential growth and on nonunimodular graphs (Hutchcroft 2016, 2020). Open on Z^3 to Z^10."),
dict(id="T002", d="PERC", t="Conformal invariance and universality of planar critical percolation",
 s="Critical bond percolation on Z^2, and site percolation on other periodic planar lattices suitably (isotropically) embedded, has a conformally invariant scaling limit: crossing probabilities converge to Cardy's formula and exploration interfaces converge to SLE(6). On Z^2 this would give the arm exponents and ν = 4/3, β = 5/36.",
 src="R. Langlands, P. Pouliot and Y. Saint-Aubin, Conformal invariance in two-dimensional percolation, Bull. Amer. Math. Soc. 30 (1994); O. Schramm, Conformally invariant scaling limits: an overview and a collection of problems, Proc. ICM 2006",
 loc="Schramm ICM 2006, Section 2 (to verify)",
 url="https://arxiv.org/abs/math/0602151",
 why="Smirnov's 2001 proof covers only site percolation on the triangular lattice; why all planar lattices give the same limit is the central universality question of 2D statistical mechanics.",
 st="Known only for site percolation on the triangular lattice (Smirnov 2001; exponents by Lawler–Schramm–Werner and Smirnov–Werner 2001). On Z^2: RSW theory, Kesten's scaling relations (1987), and rotational invariance for FK models with 1 ≤ q ≤ 4, q = 1 included (Duminil-Copin–Kozlowski–Krachun–Manolescu–Oulamara, arXiv:2012.11672, whose abstract names Bernoulli percolation on the square lattice). Two claimed proofs of conformal invariance for bond percolation on Z^2, Tsai–Yam–Zhou (arXiv:1112.2017, 2011) and Zhou (arXiv:2409.03235, 2024), have not been accepted as far as checked; a solver should read both first. Conformal invariance on Z^2 is open. T002 is the q = 1 case of T013."),
dict(id="T003", d="SM", t="The planar self-avoiding walk converges to SLE(8/3)",
 s="The self-avoiding walk on a planar lattice, taken chordally in a domain at the critical fugacity x_c = 1/μ, converges in the scaling limit to chordal SLE(8/3); and the uniform n-step walk has mean-square end-to-end distance of order n^{2ν} with ν = 3/4.",
 src="B. Nienhuis, Exact critical point and critical exponents of O(n) models in two dimensions, Phys. Rev. Lett. 49 (1982); G. Lawler, O. Schramm and W. Werner, On the scaling limit of planar self-avoiding walk, Proc. Sympos. Pure Math. 72 (2004)",
 loc="Lawler–Schramm–Werner 2004, Section 3 (the conjectures are unnumbered: 3.2 critical exponents, 3.4 scaling limit)",
 url="https://arxiv.org/abs/math/0204277",
 why="The flagship problem for two-dimensional polymers. SLE(8/3) is forced by the restriction property; only the existence of the limit is missing.",
 st="The connective constant of the honeycomb lattice is √(2+√2) (Duminil-Copin–Smirnov 2012) and the walk is sub-ballistic (Duminil-Copin–Hammond 2013). On random quadrangulations the walk converges to SLE(8/3) on √(8/3)-Liouville quantum gravity (Gwynne–Miller, arXiv:1608.00956), a random geometry rather than a lattice. No scaling limit and no exponent is proved on any planar lattice."),
dict(id='T004',
 x='REPORTED SOLVED (claim): p_c < p_u for nonamenable quasi-transitive graphs is claimed by an October 2026 preprint; our audit of its section 9 found the argument sound given its sub-power bounds. Held on the watch list; restored if the claim fails.',
 d='PERC',
 t='p_c < p_u on every nonamenable quasi-transitive graph',
 s='For every connected, locally finite, quasi-transitive nonamenable graph, the critical probability p_c for an infinite cluster is strictly smaller than the uniqueness threshold p_u, so an intermediate phase with infinitely many infinite clusters exists.',
 c='The converse (amenable implies at most one infinite cluster, so p_c = p_u) is Burton–Keane 1989.',
 src='I. Benjamini and O. Schramm, Percolation beyond Z^d, many questions and a few answers, Electron. Comm. Probab. 1 (1996)',
 loc='Benjamini–Schramm 1996, Conjecture 6 (confirmed: Häggström 2011, Conjecture 2.7)',
 url='https://doi.org/10.1214/ECP.v1-978',
 why='It would characterise amenability by percolation; the best-known question of percolation beyond Z^d.',
 st='Proved for planar nonamenable graphs (Benjamini–Schramm 2001), Gromov hyperbolic graphs (Hutchcroft 2019), nonunimodular quasi-transitive graphs (Hutchcroft, J. Amer. Math. Soc. 33, 2020), nonamenable Cayley graphs of high girth (Nachmias–Peres, Electron. Commun. Probab. 17, 2012), highly nonamenable graphs and products with trees (several authors), and for some Cayley graph of every nonamenable group (Pak–Smirnova-Nagnibeda 2000). Open in general.'),
dict(id="T005", d="IPS", t="KPZ universality beyond exactly solvable models",
 s="Last-passage percolation, directed polymers and random growth in 1+1 dimensions with general non-degenerate, light-tailed weights or noise have fluctuations of order n^{1/3} with Tracy–Widom limits whose type depends on the geometry (GUE point-to-point, GOE point-to-line), transversal fluctuations of order n^{2/3}, and converge to the KPZ fixed point and the directed landscape.",
 src="M. Kardar, G. Parisi and Y.-C. Zhang, Dynamic scaling of growing interfaces, Phys. Rev. Lett. 56 (1986); I. Corwin, The Kardar–Parisi–Zhang equation and universality class, Random Matrices Theory Appl. 1 (2012)",
 loc="Corwin 2012, Section 1 (to verify)",
 url="https://arxiv.org/abs/1106.1596",
 why="Universality is the content of the KPZ conjecture, and every proof so far rests on an exact formula of an integrable model.",
 st="Proved for integrable models: Poissonian LPP (Baik–Deift–Johansson 1999), geometric and exponential LPP (Johansson 2000), ASEP (Tracy–Widom 2009), the log-gamma and other solvable polymers, the KPZ equation (Amir–Corwin–Quastel 2011), convergence to the directed landscape for integrable LPP (Dauvergne–Ortmann–Virág 2022) and of the KPZ equation to the KPZ fixed point (Quastel–Sarkar 2023; Virág 2020). For general iid weights even the exponent 1/3 is unproved."),
dict(id="T006", d="PERC", t="Fluctuation exponents of first-passage percolation",
 s="For first-passage percolation on Z^2 with iid nonnegative continuous edge weights with enough moments, Var T(0, nx) is of order n^{2/3} and geodesics wander distance n^{2/3} from the straight line; in every dimension the exponents satisfy χ = 2ξ − 1.",
 src="H. Kesten, On the speed of convergence in first-passage percolation, Ann. Appl. Probab. 3 (1993); A. Auffinger, M. Damron and J. Hanson, 50 Years of First-Passage Percolation (AMS, 2017)",
 loc="Auffinger–Damron–Hanson 2017, Chapter 3 and the open questions there (to verify)",
 url="https://arxiv.org/abs/1511.03262",
 why="FPP is the oldest model expected in the KPZ class; the distance between the known bounds and n^{2/3} measures how little of KPZ is understood outside integrable cases.",
 st="Known: Var T ≤ Cn (Kesten 1993) and ≤ Cn/log n (Benjamini–Kalai–Schramm 2003; extended by Benaïm–Rossignol and Damron–Hanson–Sosoe); lower bounds of order log n in d = 2 (Newman–Piza 1995, Pemantle–Peres 1994). χ = 2ξ − 1 is proved assuming the exponents exist (Chatterjee 2013; Auffinger–Damron 2014). The exponents are open."),
dict(id="T007", d="SM", t="Polyakov's conjecture: the planar O(N) model with N ≥ 3 has a mass gap at every temperature",
 s="For the classical O(N) spin model on Z^2 (spins on the sphere S^{N−1}, nearest-neighbour ferromagnetic coupling) with N ≥ 3, spin correlations decay exponentially at every inverse temperature β.",
 src="A. M. Polyakov, Interaction of Goldstone particles in two dimensions. Applications to ferromagnets and massive Yang–Mills fields, Phys. Lett. B 59 (1975)",
 why="The lattice model of asymptotic freedom. It separates N = 2, where the Berezinskii–Kosterlitz–Thouless transition holds (Fröhlich–Spencer 1981), from N ≥ 3, and its four-dimensional gauge analogue is the mass-gap problem.",
 st="Open for every N ≥ 3. Known: no spontaneous magnetisation (Mermin–Wagner), exponential decay at high temperature, the large-N limit. Patrascioiu and Seiler argued for a massless low-temperature phase instead, so the conjecture is not universally believed. Aru–Garban–Sepúlveda (arXiv:2212.06767) still treat it as open; a search on 14 Oct found no 2025–26 claim.",
 url="https://arxiv.org/abs/1708.00058",
 loc="Peled–Spinka, Lectures on the spin and loop O(n) models, Section 2.2"),
dict(id="T008", d="SM", t="Critical behaviour of the three-dimensional Ising model",
 s="At the critical temperature the nearest-neighbour Ising model on Z^3 has ⟨σ_0σ_x⟩ = |x|^{−(1+η)+o(1)} for some 0 < η < 1, its critical exponents exist, and its scaling limit is a non-Gaussian conformally invariant field (the 3D Ising CFT; η ≈ 0.0363 by the conformal bootstrap).",
 c="As stated this is a programme; the checkable forms are the existence of η and the non-Gaussianity of the scaling limit.",
 src="A. M. Polyakov, Conformal symmetry of critical fluctuations, JETP Lett. 12 (1970); H. Duminil-Copin, 100 years of the (critical) Ising model on the hypercubic lattice, Proc. ICM 2022",
 loc="Duminil-Copin ICM 2022, open problems (to verify)",
 url="https://arxiv.org/abs/2208.00864",
 why="The most studied unsolved model of statistical mechanics; d = 3 lies below the upper critical dimension and no exact solution is expected.",
 st="Known in d = 3: continuity of the transition (Aizenman–Duminil-Copin–Sidoravicius 2015), sharpness, and c|x|^{−2} ≤ ⟨σ_0σ_x⟩ ≤ C|x|^{−1} at criticality (Simon–Lieb and the infrared bound). Triviality is proved for d ≥ 5 (Aizenman 1982, Fröhlich 1982) and d = 4 (Aizenman–Duminil-Copin 2021). Existence of exponents in d = 3 is open."),
dict(id="T009", d="RMT", t="Extended states for the Anderson model in three dimensions",
 s="For the Anderson model H = −Δ + λV on ℓ²(Z^d), d ≥ 3, with iid potential V whose single-site law is non-degenerate with a bounded density, and small disorder λ, some interval of energies carries absolutely continuous spectrum (delocalised states).",
 src="P. W. Anderson, Absence of diffusion in certain random lattices, Phys. Rev. 109 (1958); B. Simon, Schrödinger operators in the twenty-first century, in Mathematical Physics 2000 (Imperial College Press, 2000)",
 loc="Simon 2000, Problem 1 (confirmed)",
 why="Localization is proved in many regimes, but delocalization for a random operator on Z^d never has been; the main open problem of random Schrödinger operators.",
 st="An OpenAI preprint (23 Sep 2026, on GitHub, unrefereed) proves purely absolutely continuous spectrum on a fixed interval near the bottom of the band for iid uniform potentials, every d ≥ 3 and small λ; Jakšić–Last (arXiv:2610.11611) cite it. Before that: absolutely continuous spectrum on regular trees (Klein 1998; Aizenman–Sims–Warzel 2006; Aizenman–Warzel 2013), quantum diffusion up to times of order λ^{−2−κ} in d ≥ 3 (Erdős–Salmhofer–Yau 2007–08), localization at large disorder and band edges (Fröhlich–Spencer 1983, Aizenman–Molchanov 1993). Becker–Oltman (arXiv:2609.20798) treat the product of Z^d with a hyperbolic lattice, not Z^d. General bounded-density laws are open.",
 url="https://web.ma.utexas.edu/mp_arc/a/00-78",
 x="REPORTED SOLVED for the uniform law: an OpenAI preprint, Absolutely Continuous Spectrum for Weak-Disorder Anderson Models in Dimensions at Least Three (23 Sep 2026, posted on GitHub, not on arXiv, unrefereed: https://raw.githubusercontent.com/openai/math/main/preprints/Absolutely-Continuous-Spectrum-for-Weak-Disorder-Anderson-Models-in-Dimensions-at-Least-Three-September-23-2026/paper.pdf), proves for iid potentials uniform on [−1, 1] that for every d ≥ 3 there is λ_d > 0 such that for 0 < λ < λ_d the spectrum on a fixed interval I_d near the bottom of the band, (−6 + e_2/2, −6 + e_2) for d = 3 and −2d + (1/200, 1/100) for d ≥ 4, is almost surely nonempty and purely absolutely continuous (Theorem 1.1). The paper says it settles Simon's Problem 1 for this model; it does not locate the mobility edge or treat quantum diffusion (Simon's Problem 3), and general bounded-density laws, which this row asks for, are not covered. It is the preprint Jakšić–Last cite. Read from the paper 14 Oct by the w673 audit."),
dict(id="T010", d="RMT", t="Localization of the two-dimensional Anderson model at every disorder",
 s="For the Anderson model on ℓ²(Z^2) with iid non-degenerate potential (not almost surely constant) of any strength λ > 0, the spectrum is pure point with exponentially decaying eigenfunctions.",
 src="E. Abrahams, P. W. Anderson, D. C. Licciardello and T. V. Ramakrishnan, Scaling theory of localization, Phys. Rev. Lett. 42 (1979); B. Simon (2000), as in T009",
 loc="Simon 2000, Problem 2 (confirmed)",
 why="The scaling theory makes d = 2 the marginal dimension and predicts localization at any disorder; a proof at weak disorder would need control on all scales.",
 st="Known at large disorder and band edges; near the spectral edge for Bernoulli potentials on Z^2 (Ding–Smart 2020) and Z^3 (Li–Zhang 2022). In d = 1 localization holds at all disorders (Goldsheid–Molchanov–Pastur 1977, Kunz–Souillard 1980). Weak disorder in d = 2 is open. Update, 14 Nov 2026: the OpenAI math release (github.com/openai/math; AI-written, unrefereed) has 'Pure-Point Spectrum for the Two-Dimensional Anderson Model at Every Positive Disorder' (23 Sep 2026), which claims pure-point spectrum throughout the spectrum for iid uniform potentials at every positive disorder, without exponential decay of eigenfunctions; other laws and the decay remain open.",
 url="https://web.ma.utexas.edu/mp_arc/a/00-78"),
dict(id="T011", d="SM", t="Confinement in four-dimensional lattice Yang–Mills theory",
 s="For four-dimensional lattice Yang–Mills theory with Wilson action and any compact non-Abelian gauge group G ⊆ U(N), N ≥ 2 (SU(2) and SU(3) are the main cases), at every coupling β, Wilson loops of rectangular R × T loops obey an area law |⟨W_{R,T}⟩| ≤ C(β) e^{−c(β)RT}, and the theory has a mass gap.",
 c="The continuum version (existence and mass gap) is a Clay Millennium problem; this row is the lattice, probabilistic form.",
 src="K. G. Wilson, Confinement of quarks, Phys. Rev. D 10 (1974); S. Chatterjee, Yang–Mills for probabilists, in Probability and Analysis in Interacting Physical Systems (Springer, 2019)",
 loc="Chatterjee 2019, Problems 4.1 and 5.1",
 url="https://arxiv.org/abs/1803.01950",
 why="The deepest open problem joining probability and particle physics: confinement at weak coupling is the physics of the strong force.",
 st="Known: area law at strong coupling (Osterwalder–Seiler 1978); two-dimensional theories solved (Gross, Driver, Sengupta, Lévy); deconfinement for U(1) in 4D at weak coupling (Guth 1980, Fröhlich–Spencer 1982); Wilson-loop results at strong coupling, large N and for finite gauge groups (Chatterjee, Ising lattice gauge theory, arXiv:1811.09770; Jafarov, SU(N), arXiv:1610.03821; Basu–Ganguly, SO(N), arXiv:1608.04379; Adhikari–Cao, finite groups at weak coupling, arXiv:2202.10375; Cao–Park–Sheffield, arXiv:2307.06790). Weak coupling for SU(N) on Z^4 is open."),
dict(id="T012", d="IPS", t="Infinite cycles in the random interchange process on Z^3 and Z^4 (Tóth's conjecture)",
 s="In the random interchange process on Z^3 and Z^4 (each edge has a rate-one Poisson clock and transposes its endpoints when it rings), the random permutation at time β has infinite cycles for every large β. Tóth's representation of the spin-1/2 quantum Heisenberg ferromagnet uses the same process weighted by 2^{#cycles}; long-range order there is a related but separate question.",
 src="B. Tóth, Improved lower bound on the thermodynamic pressure of the spin 1/2 Heisenberg ferromagnet, Lett. Math. Phys. 28 (1993)",
 loc="Tóth 1993, as quoted in Elboim–Sly 2022, Section 1",
 why="Order in the quantum Heisenberg ferromagnet in d = 3 is a famous open problem of quantum statistical mechanics (for the antiferromagnet reflection positivity gives order, Dyson–Lieb–Simon 1978); the interchange process makes it a question about random permutations.",
 st="Proved on Z^d for every d ≥ 5 at every large β (D. Elboim and A. Sly, arXiv:2211.17023, 2022). Earlier: regular trees of high degree (Angel 2003; Hammond, arXiv:1202.1319 and 1202.1322), the complete graph with Poisson–Dirichlet cycle structure (Schramm, arXiv:math/0404356; Berestycki–Kozma, arXiv:1205.4753), the hypercube (Kotecký–Miłoś–Ueltschi, arXiv:1509.02067), Hamming graphs (Miłoś–Şengül, arXiv:1605.03548; Adamczak–Kotowski–Miłoś, arXiv:1808.08902) and random regular graphs (Poudevigne, arXiv:2209.13370). Open for d = 3 and 4.",
 url="https://arxiv.org/abs/2211.17023",
 c="Tóth's conjecture (1993), as quoted by Elboim and Sly: on Z^2 only finite cycles at every β > 0, and on Z^d, d ≥ 3, infinite cycles for every β > β_c. The planar half is open too. The row was first written for every d ≥ 3; the case d ≥ 5 is proved (see where it stands)."),
]
